// ════════════════════════════════════════════════════════════════════════
// tools/lib/generated-target.mjs — WHICH FILE A CATALOGUE GENERATOR OWNS NOW.
//
// A generator's output is the NEWEST migration in the apply order
// (tools/lib/apply-order.mjs) that it wrote (its own "Generated by tools/<tool>"
// header line), never a hard-coded name: two lanes that each add a forward file
// (2026-10-26 slot starter, 2026-10-27 core rebuild) then agree on which one
// `--check` grades.
//
// An APPLIED file is never rewritten (CLAUDE.md §2: production runs it as it
// was reviewed). When the newest owned file is APPLIED, a write is refused and
// names the way forward: `--new <slug>` writes a NEW sequence-named file
// (NNNN-<slug>.generated.sql, rule 12) and its sidecar with a STAGED note, so no
// shared file is edited to place it.
// ════════════════════════════════════════════════════════════════════════
import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { loadApplyOrder, nextMigrationName, registerNew, isSeqName, SLUG, NOTES_DIR, noteFileOf } from './apply-order.mjs';

/**
 * @param {string} root  the repo root
 * @param {string} tool  e.g. 'gen-unlocks.mjs'
 * @returns {{ file: string, path: string, applied: boolean } | null}
 */
export function newestOwned(root, tool) {
  const manifest = loadApplyOrder(root, { disk: false });
  const sig = 'Generated by tools/' + tool;
  for (let i = manifest.order.length - 1; i >= 0; i--) {
    const file = manifest.order[i];
    const path = join(root, 'supabase', 'migrations', file);
    if (!existsSync(path) || !readFileSync(path, 'utf8').includes(sig)) continue;
    const note = (manifest._order_notes || {})[file];
    return { file, path, applied: typeof note === 'string' && /^APPLIED\b/.test(note) };
  }
  return null;
}

/**
 * Where a generator writes (or checks): `--new <slug>` (or a full NNNN-<slug>.generated.sql name)
 * for a new forward file, else the newest owned file. `write` refuses an APPLIED target, and on a
 * `--new` write registers the new file's sidecar (its STAGED note) before returning the path.
 * @returns {string} the absolute path
 */
export function generatedTarget(root, tool, argv, { write, die }) {
  const at = argv.indexOf('--new');
  if (at >= 0) {
    const arg = argv[at + 1] || '';
    let name;
    if (isSeqName(arg) && arg.endsWith('.generated.sql')) name = arg;
    else if (SLUG.test(arg)) name = nextMigrationName(root, arg, { generated: true });
    else die('--new wants a slug (lower-case words joined by hyphens): the file is named NNNN-<slug>.generated.sql at the next sequence');
    const path = join(root, 'supabase', 'migrations', name);
    if (existsSync(path)) die(name + ' already exists; --new is for a NEW forward file');
    if (write && !existsSync(join(root, NOTES_DIR, noteFileOf(name)))) {
      registerNew(root, name, `STAGED, NOT APPLIED (written by tools/${tool} --new; the author completes this note: lane, role, date, `
        + 'what moves, ORDER, EDGE).');
    }
    return path;
  }
  const t = newestOwned(root, tool);
  if (!t) die('no migration in the apply order carries "Generated by tools/' + tool + '"');
  if (write && t.applied) {
    die(t.file + ' is APPLIED and is never rewritten. Run: node tools/' + tool
      + ' --new <slug>: a NEW NNNN-<slug>.generated.sql with its STAGED sidecar (supabase/migration-notes)');
  }
  return t.path;
}
